mapper.select:
select od.name as name, ifnull(sum(od.number),0) as number
from order_detail od join orders o on od.order_id = o.id
where o.status = #{status}
  and o.order_time >= #{begin} and o.order_time <= #{end}
group by od.name order by number desc limit 10

select od.dish_id as dishId, sum(greatest(coalesce(od.number, 1), 1)) as quantity
from order_detail od join orders o on od.order_id = o.id
join dish d on d.id = od.dish_id
join address_book a on a.id = o.address_book_id
where o.status = 5 and o.order_time >= #{begin} and o.order_time < #{end}

    and o.user_id in
    #{userId}

and a.district_name = #{district}
group by od.dish_id order by quantity desc
limit #{limit}
